    // 读取 CSV 并输出总和
}

private.reference_solution:
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__") || input.isEmpty()) System.exit(1);
        int total = 0;
        for (String part : input.split(",")) total += Integer.parseInt(part.trim());
        System.out.println(total);
    }
}
